// Worker 侧补挂安全响应头。
//
// 【为什么需要这个文件】Cloudflare 的 _headers **只作用于静态资源响应**，Worker 代码
// 自己 return 的响应不吃它——官方文档原话：「Custom headers defined in the _headers
// file are not applied to responses generated by your Worker code, even if the request
// URL matches a rule」（developers.cloudflare.com/workers/static-assets/headers）。
// 本站开了 run_worker_first（wrangler.jsonc），首页、/songs/、/jubility/、/recent/、
// /login、/register、/account、/admin 与全部 /api/* 都先交给 Worker，于是这些页
// 一个头都拿不到。线上实测（2026-11-04）：/ 与 /songs/ 的四个安全头全缺，
// /manifest.webmanifest 与 /robots.txt（静态层）却有——同一份 _headers，两种结果。
//
// 【所以头有两个落点，必须同时改】
//   · public/_headers        → 静态资源（/assets/**、404.html、manifest、robots.txt…）
//   · src/lib/csp.ts（本文件）→ Worker 渲染的响应（页面与 API）
// 两边内容重复是**故意的**：一个是构建期纯文本、一个是运行时字符串，没法共享。
// 改任何一条策略都得两处一起改，_headers 那边有同样的清单注释。
//
// 【只挂那几个静态头，不在这里做别的】保持中间件原职责（会话解析 + 边缘缓存），
// 补头是纯粹的响应修饰，放在最外层统一处理，页面里不必各写一遍。

/** 静态响应头。值与 public/_headers 里那份**逐字一致**，改一处就得改两处。 */
const STATIC_HEADERS: ReadonlyArray<readonly [string, string]> = [
  ['x-content-type-options', 'nosniff'],
  ['x-frame-options', 'SAMEORIGIN'],
  ['referrer-policy', 'strict-origin-when-cross-origin'],
  ['permissions-policy', 'geolocation=(), microphone=(), camera=()'],
  [
    'content-security-policy-report-only',
    "default-src 'self'; script-src 'self' https://challenges.cloudflare.com; script-src-attr 'none'; " +
      "style-src 'self' https://challenges.cloudflare.com; style-src-attr 'unsafe-inline'; " +
      "img-src 'self' data: https://img.shields.io; font-src 'self'; media-src 'self'; " +
      "connect-src 'self' https://challenges.cloudflare.com; " +
      "frame-src https://challenges.cloudflare.com; manifest-src 'self'; worker-src 'self'; " +
      "object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; " +
      'upgrade-insecure-requests; report-uri /api/csp-report',
  ],
];

/**
 * 给响应补上安全头。
 *
 * 只补调用方没自己设过的（`set` 会覆盖，用 `has` 让页面能按需顶掉某一条，
 * 比如将来某个接口确实要放宽 XFO）。头已经在的照旧，不重复写。
 *
 * 响应头是不可变的（Response 构造后 headers 只读），所以必须复制一份——
 * body 用流透传，不读进内存。
 */
export function withSecurityHeaders(res: Response): Response {
  const headers = new Headers(res.headers);
  for (const [name, value] of STATIC_HEADERS) {
    if (!headers.has(name)) headers.set(name, value);
  }
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}
